import spidev
import time
import signal

class LoadCellReader:
    def __init__(self):
        self.spi = None
        try:
            self.spi = spidev.SpiDev()
            self.spi.open(0, 0)
            self.spi.max_speed_hz = 50000
            self.spi.mode = 0b00
            self.spi.bits_per_word = 8
        except (OSError, IOError) as e:
            print(f"Error opening SPI device: {e}")
            self.close()

    def read_raw_data(self):
        if self.spi is None:
            print("SPI device not open, cannot read data.")
            return None

        try:
            response = self.send_spi_command(self.spi)
            raw_data = self.extract_10bit(response)
            return raw_data
        except (OSError, IOError) as e:
            print(f"Error reading data: {e}")
            self.close()
            return None

    def convert_to_weight(self, raw_data):
        if raw_data is None:
            return None

        weight = float(raw_data) * (5.0 / 1023.0)
        return weight

    def close(self):
        if self.spi is not None:
            self.spi.close()
            self.spi = None

def send_spi_command(spi, data):
    return spi.xfer2(data)

def extract_10bit(response):
    return ((response[1] & 0x03) << 8) | response[2]

def main():
    reader = LoadCellReader()

    try:
        while True:
            raw_data = reader.read_raw_data()
            if raw_data is not None:
                weight = reader.convert_to_weight(raw_data)
                if weight is not None:
                    print(f"Weight: {weight:.2f} kg")
            time.sleep(0.5)
    except KeyboardInterrupt:
        print("KeyboardInterrupt caught, shutting down...")
    except Exception as e:
        print(f"Fatal error: {e}")
    finally:
        reader.close()
        print("SPI device closed.")

def signal_handler(sig, frame):
    print("SIGTERM received, shutting down...")
    sys.exit(0)

signal.signal(signal.SIGTERM, signal_handler)

if __name__ == "__main__":
    main()

