import smbus2
import logging
import signal
import time

class ADS1015:
    def __init__(self, address=0x48, busnum=1, debug=False):
        self.address = address
        self.busnum = busnum
        self.debug = debug
        self.bus = smbus2.SMBus(self.busnum)
        self.verify_device()

    def verify_device(self):
        try:
            config_register = self.bus.read_byte_data(self.address, 0x00)
            if config_register == 0x00:
                logging.info("ADS1015 device verified at address 0x%02X on bus %d", self.address, self.busnum)
            else:
                logging.error("Unexpected configuration register value 0x%02X, device may not be present", config_register)
        except IOError as e:
            logging.error("Error verifying device: %s", str(e))

    def read_adc_single_ended(self, channel=0, pga=6144, sps=250):
        try:
            config = 0x00 | (channel & 0x03) | ((pga >> 3) & 0x0C) | ((sps >> 4) & 0x30)
            self.bus.write_byte_data(self.address, 0x00, config)
            time.sleep(0.001)  # Wait for conversion
            data = self.bus.read_i2c_block_data(self.address, 0x00, 2)
            result = (data[1] << 8) | data[0]
            return result
        except IOError as e:
            logging.error("Error reading ADC: %s", str(e))

    def start_continuous_conversion(self, channel=0, pga=6144, sps=250):
        try:
            config = 0x80 | (channel & 0x03) | ((pga >> 3) & 0x0C) | ((sps >> 4) & 0x30)
            self.bus.write_byte_data(self.address, 0x00, config)
        except IOError as e:
            logging.error("Error starting continuous conversion: %s", str(e))

    def get_last_conversion_results(self):
        try:
            data = self.bus.read_i2c_block_data(self.address, 0x00, 2)
            result = (data[1] << 8) | data[0]
            return result
        except IOError as e:
            logging.error("Error getting last conversion result: %s", str(e))

    def start_single_ended_comparator(self, channel=0, threshold_high=2047, threshold_low=0, pga=6144, sps=250, active_low=True, traditional_mode=True, latching=False, num_readings=1):
        try:
            config = 0x80 | (channel & 0x03) | ((pga >> 3) & 0x0C) | ((sps >> 4) & 0x30)
            if active_low:
                config |= 0x01
            if traditional_mode:
                config |= 0x02
            if latching:
                config |= 0x04
            config |= (threshold_high & 0x0F) << 4
            config |= (threshold_low & 0x0F) << 8
            self.bus.write_byte_data(self.address, 0x00, config)
        except IOError as e:
            logging.error("Error starting single-ended comparator: %s", str(e))

    def __del__(self):
        try:
            self.bus.close()
            logging.info("I2C bus closed successfully")
        except IOError as e:
            logging.error("Error closing I2C bus: %s", str(e))

def signal_handler(sig, frame):
    print('Received signal %d, cleaning up...' % sig)
    sys.exit(0)

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

# Example usage
if __name__ == "__main__":
    adc = ADS1015()
    print(adc.read_adc_single_ended())

