import smbus
import time
import signal

# Constants
ADS1115_ADDRESS = 0x48
ADS1115_REG_CONFIG = 0x00
ADS1115_REG_CONVERSION = 0x00
ADS1115_REG_RESULT = 0x00
MAX_BATTERY_VOLTAGE = 13.8
MIN_BATTERY_VOLTAGE = 10.5
R1 = 2000
R2 = 1000
HYS_THRESHOLD = 1

# Voltage divider calculation
def calculate_voltage(adc_value):
    voltage = (adc_value * 6.144) / 65536
    return voltage * (R1 + R2) / R2

# Battery percentage calculation
def calculate_battery_percentage(voltage):
    if voltage > MAX_BATTERY_VOLTAGE:
        return 100
    elif voltage < MIN_BATTERY_VOLTAGE:
        return 0
    else:
        return int((voltage - MIN_BATTERY_VOLTAGE) / (MAX_BATTERY_VOLTAGE - MIN_BATTERY_VOLTAGE) * 100)

# I2C bus initialization
def initialize_i2c():
    try:
        bus = smbus.SMBus(1)
        return bus
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        return None

# Configure ADS1115
def configure_ads1115(bus):
    if bus is None:
        return False
    try:
        bus.write_byte_data(ADS1115_ADDRESS, ADS1115_REG_CONFIG, 0x86)  # Set PGA to +/-6.144V, MUX to A0, and single-shot mode
        return True
    except Exception as e:
        print(f"Error configuring ADS1115: {e}")
        return False

# Read ADC value
def read_adc_value(bus):
    if bus is None:
        return None
    try:
        high_byte = bus.read_byte_data(ADS1115_ADDRESS, ADS1115_REG_RESULT)
        low_byte = bus.read_byte_data(ADS1115_ADDRESS, ADS1115_REG_RESULT + 1)
        adc_value = (high_byte << 8) | low_byte
        return adc_value
    except Exception as e:
        print(f"Error reading ADC value: {e}")
        return None

# Main loop
def main():
    bus = initialize_i2c()
    if bus is None:
        return

    if not configure_ads1115(bus):
        return

    last_percentage = 0
    while True:
        adc_value = read_adc_value(bus)
        if adc_value is not None:
            voltage = calculate_voltage(adc_value)
            percentage = calculate_battery_percentage(voltage)
            if abs(percentage - last_percentage) > HYS_THRESHOLD:
                print(f"Battery Voltage: {voltage:.2f}V, Percentage: {percentage}%")
                last_percentage = percentage
        time.sleep(1)

# Graceful exit on KeyboardInterrupt
def signal_handler(sig, frame):
    print("Exiting...")
    exit(0)

signal.signal(signal.SIGINT, signal_handler)

if __name__ == "__main__":
    main()

