import spidev
import RPi.GPIO as GPIO
import time
import logging

class SmartGardenController:
    def __init__(self):
        self.spi = spidev.SpiDev()
        self.spi.open(0, 0)
        self.spi.max_speed_hz = 1350000
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(18, GPIO.OUT)
        self.logger = logging.getLogger(__name__)

    def read_moisture(self):
        try:
            command = [1 << 7, 0 << 6, 0 << 5, 0 << 4]  # Start bit, single-ended mode, channel select
            result = self.spi.xfer2(command)
            moisture_value = (result[1] & 0x0F) * 256 + result[2]
            return moisture_value
        except Exception as e:
            self.logger.error(f"Error reading moisture: {e}")
            return None

    def run_pump(self, seconds):
        GPIO.output(18, GPIO.HIGH)
        time.sleep(seconds)
        GPIO.output(18, GPIO.LOW)

    def irrigation_cycle(self, dry_threshold=450):
        moisture_value = self.read_moisture()
        if moisture_value is not None and moisture_value > dry_threshold:
            self.run_pump(2)
            return True
        return False

    def close(self):
        self.spi.close()
        GPIO.cleanup()

def schedule_cycles(controller, cycle_count, interval_seconds):
    for _ in range(cycle_count):
        controller.irrigation_cycle()
        time.sleep(interval_seconds)

if __name__ == "__main__":
    try:
        controller = SmartGardenController()
        schedule_cycles(controller, 10, 3)
    except Exception as e:
        logging.error(f"An error occurred: {e}")
    finally:
        if hasattr(controller, 'close'):
            controller.close()

