import argparse
import logging
import time
import queue
import threading
import RPi.GPIO as GPIO
import spidev

# Constants
DEBOUNCE_TIME = 0.1

class SoundSensor:
    def __init__(self, sensor_id, sensor_type, threshold, sample_rate, gpio_pins=None, channels=None, spi_speed=1000000, log_queue=None):
        self.sensor_id = sensor_id
        self.sensor_type = sensor_type
        self.threshold = threshold
        self.sample_rate = sample_rate
        self.log_queue = log_queue
        self.spi = None
        self.gpio_pins = gpio_pins
        self.channels = channels
        self.spi_speed = spi_speed

        if self.sensor_type == "analog":
            self.setup_analog()
        elif self.sensor_type == "digital":
            self.setup_digital()
        else:
            logging.error(f"Invalid sensor type: {self.sensor_type}")

    def setup_analog(self):
        try:
            self.spi = spidev.SpiDev()
            self.spi.open(0, 0)
            self.spi.max_speed_hz = self.spi_speed
        except Exception as e:
            logging.error(f"Failed to initialize SPI: {e}")

    def setup_digital(self):
        GPIO.setmode(GPIO.BCM)
        for pin in self.gpio_pins:
            GPIO.setup(pin, GPIO.IN)

    def read_analog(self, channel):
        if self.spi is None:
            return None
        try:
            adc_value = self.spi.xfer2([1, (8 + channel) << 4, 0])[1] & 3
            adc_value = (adc_value << 8) + self.spi.xfer2([1, (8 + channel) << 4, 0])[2]
            return adc_value
        except Exception as e:
            logging.error(f"Failed to read ADC: {e}")
            return None

    def read_digital(self, pin):
        try:
            return GPIO.input(pin)
        except Exception as e:
            logging.error(f"Failed to read GPIO: {e}")
            return None

    def run(self):
        last_event_time = 0
        while True:
            if self.sensor_type == "analog":
                adc_value = self.read_analog(self.channels[0])
                if adc_value is not None and adc_value >= self.threshold:
                    if time.time() - last_event_time >= DEBOUNCE_TIME:
                        self.log_queue.put(f"Sensor {self.sensor_id}: Analog event detected (ADC value: {adc_value})")
                        last_event_time = time.time()
            elif self.sensor_type == "digital":
                digital_value = self.read_digital(self.gpio_pins[0])
                if digital_value is not None and digital_value == 1:
                    if time.time() - last_event_time >= DEBOUNCE_TIME:
                        self.log_queue.put(f"Sensor {self.sensor_id}: Digital event detected")
                        last_event_time = time.time()
            time.sleep(1 / self.sample_rate)

    def stop(self):
        if self.sensor_type == "analog":
            self.spi.close()
        elif self.sensor_type == "digital":
            GPIO.cleanup()

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--sensor_type", choices=["analog", "digital"], required=True)
    parser.add_argument("--threshold", type=int, required=True)
    parser.add_argument("--sample_rate", type=int, required=True)
    parser.add_argument("--log_file", required=True)
    parser.add_argument("--gpio_pins", type=int, nargs='+', required=True)
    parser.add_argument("--channels", type=int, nargs='+', required=True)
    parser.add_argument("--spi_speed", type=int, default=1000000)
    parser.add_argument("--sensor_ids", type=int, nargs='+', required=True)
    args = parser.parse_args()

    log_queue = queue.Queue()
    logging.basicConfig(filename=args.log_file, level=logging.ERROR)

    sensors = []
    for sensor_id in args.sensor_ids:
        sensors.append(SoundSensor(sensor_id, args.sensor_type, args.threshold, args.sample_rate, args.gpio_pins, args.channels, args.spi_speed, log_queue))

    threads = []
    for sensor in sensors:
        thread = threading.Thread(target=sensor.run)
        thread.start()
        threads.append(thread)

    try:
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        for sensor in sensors:
