def initialize_camera():
    try:
        camera = picamera2.PiCamera()
        camera.resolution = (640, 480)
        camera.framerate = 15
        time.sleep(2)  # Warm-up delay
        return camera
    except picamera2.exc.PiCameraError as e:
        print(f"Error initializing camera: {e}")
        return None

def capture_baseline_image(camera):
    try:
        with picamera2.array.PiRGBArray(camera) as stream:
            camera.capture(stream, format='rgb')
            baseline_image = stream.array
            return baseline_image
    except picamera2.exc.PiCameraError as e:
        print(f"Error capturing baseline image: {e}")
        return None

def capture_and_detect_motion(camera, baseline_image):
    baseline_average = np.mean(baseline_image)
    while True:
        try:
            with picamera2.array.PiRGBArray(camera) as stream:
                camera.capture(stream, format='rgb')
                current_image = stream.array
                current_average = np.mean(current_image)
                if abs(current_average - baseline_average) > 10:
                    print("Motion detected!")
                    current_image.save('motion.jpg')
                    baseline_average = current_average
                time.sleep(2)  # Pause between captures
        except picamera2.exc.PiCameraError as e:
            print(f"Error capturing image: {e}")

def main():
    camera = initialize_camera()
    if camera:
        baseline_image = capture_baseline_image(camera)
        if baseline_image is not None:
            capture_and_detect_motion(camera, baseline_image)
        else:
            print("Failed to capture baseline image.")
    else:
        print("Failed to initialize camera.")

if __name__ == "__main__":
    main()

