import RPi.GPIO as GPIO
import threading
import queue
import time
import logging
import signal

# Set up logging
logging.basicConfig(filename='motion_detection.log', level=logging.INFO,
                    format='%(asctime)s - %(message)s')

# Define GPIO pins
PINS = {
    'Front Door': 17,
    'Back Door': 27,
    'Living Room': 22
}

# Define debounce and sensitivity times
DEBOUNCE_TIME = 0.5
SENSITIVITY = 0.1

# Shared queue for motion events
motion_queue = queue.Queue()

# Function to handle GPIO setup and cleanup
def setup_gpio():
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(PINS.values(), GPIO.IN, pull_up_down=GPIO.PUD_DOWN)

    def cleanup():
        GPIO.cleanup()

    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

# Function to monitor GPIO pins for rising edges
def monitor_pins():
    last_trigger_time = {pin: 0 for pin in PINS.values()}
    last_motion_start = {pin: 0 for pin in PINS.values()}

    while True:
        for zone, pin in PINS.items():
            if GPIO.input(pin):
                if time.time() - last_trigger_time[pin] >= DEBOUNCE_TIME:
                    last_trigger_time[pin] = time.time()
                    if time.time() - last_motion_start[pin] >= SENSITIVITY:
                        last_motion_start[pin] = time.time()
                        motion_queue.put((time.time(), zone))
                        print(f"Motion detected in {zone} at {time.time()}")

# Main function
def main():
    setup_gpio()

    try:
        monitor_thread = threading.Thread(target=monitor_pins)
        monitor_thread.daemon = True
        monitor_thread.start()

        while True:
            event = motion_queue.get()
            logging.info(f"Motion detected at {event[0]} in {event[1]}")

    except Exception as e:
        logging.error(f"An error occurred: {str(e)}")

if __name__ == "__main__":
    main()

