class SerialConnection:
    def __init__(self, port='/dev/rfcomm4', baudrate=38400):
        self.port = port
        self.baudrate = baudrate
        self.serial = None

    def __enter__(self):
        try:
            self.serial = serial.Serial(
                port=self.port,
                baudrate=self.baudrate,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE,
                bytesize=serial.EIGHTBITS,
                timeout=1
            )
            if not self.serial.isOpen():
                self.serial.open()
        except serial.SerialException as e:
            print(f"Error opening serial port: {e}", file=sys.stderr)
            sys.exit(1)
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        if self.serial and self.serial.isOpen():
            self.serial.close()

    def send_data(self, data):
        try:
            encoded_data = data.encode('utf-8')
            sent_bytes = self.serial.write(encoded_data)
            print(f"Sent {sent_bytes} bytes: {data}")
        except serial.SerialException as e:
            print(f"Error writing to serial port: {e}", file=sys.stderr)

def signal_handler(sig, frame):
    print("Gracefully shutting down...")
    sys.exit(0)

def main():
    signal.signal(signal.SIGINT, signal_handler)

    with SerialConnection() as conn:
        while True:
            user_input = input("Enter text (or 'q' to quit): ")
            if user_input.lower() == 'q':
                break
            conn.send_data(f"X{user_input}")

if __name__ == "__main__":
