class CameraStreamBuffer:
    def __init__(self, websocket_handler):
        self.websocket_handler = websocket_handler
        self.lock = threading.Lock()
        self.buffer = io.BytesIO()

    def write(self, data):
        with self.lock:
            self.buffer.write(data)
            while b'\xff\xd8' in self.buffer.getvalue():
                start_of_jpeg = self.buffer.tell()
                jpeg_data = self.buffer.read(self.buffer.tell() - start_of_jpeg)
                if self.websocket_handler.has_connections():
                    self.websocket_handler.broadcast(jpeg_data)
                self.buffer.seek(start_of_jpeg)

    def flush(self):
        with self.lock:
            if self.buffer.tell():
                self.websocket_handler.broadcast(self.buffer.getvalue())
                self.buffer.truncate(0)

class MotionDetectionBuffer:
    def __init__(self, detect_motion_function):
        self.detect_motion_function = detect_motion_function
        self.lock = threading.Lock()
        self.buffer = io.BytesIO()
        self.previous_frame = None
        self.current_frame = None

    def write(self, data):
        with self.lock:
            self.buffer.write(data)
            while b'\xff\xd8' in self.buffer.getvalue():
                start_of_jpeg = self.buffer.tell()
                jpeg_data = self.buffer.read(self.buffer.tell() - start_of_jpeg)
                try:
                    self.current_frame = cv2.imdecode(np.frombuffer(jpeg_data, dtype=np.uint8), cv2.IMREAD_COLOR)
                    if self.previous_frame is not None:
