class GifPlayer:
    def __init__(self, spi_port=0, spi_device=0, rotation=0):
        self.device = ST7789(
            spi=spi.SPI(port=spi_port, device=spi_device, gpio=noop()),
            rotation=rotation
        )
        self.viewport = viewport(self.device, width=240, height=240)
        self.folder = None
        self.signal_received = False

