        if not os.path.isdir(folder):
            print(f"Error: Folder '{folder}' does not exist.")
            return
        self.folder = folder

    def play(self, gif_path):
        try:
            with Image.open(gif_path) as gif:
                for frame in gif.getdata():
                    frame_image = Image.frombytes('RGB', frame.size, frame)
                    padded_frame = ImageOps.pad(frame_image, (240, 240), color='black')
                    with canvas(self.viewport) as draw:
                        draw.image(padded_frame, (0, 0))
                    time.sleep(frame.info['duration'] / 1000.0 if 'duration' in frame.info else 0.1)
        except Exception as e:
            print(f"Error: Unable to process GIF '{gif_path}'. {str(e)}")

    def run(self):
        if not self.folder:
            print("Error: No folder specified for GIF files.")
            return

        for filename in os.listdir(self.folder):
            if filename.endswith('.gif'):
                gif_path = os.path.join(self.folder, filename)
                self.play(gif_path)

            if self.signal_received:
                break

    def signal_handler(self, signum, frame):
        self.signal_received = True

    def start(self):
        signal.signal(signal.SIGINT, self.signal_handler)
        signal.signal(signal.SIGTERM, self.signal_handler)

        while not self.signal_received:
            self.run()

        self.device.close()

# Example usage:
if __name__ == "__main__":
    player = GifPlayer()
    player.set_folder('/path/to/your/gif/folder')
