import time
import datetime
import logging
import subprocess
import sys
import signal
from gpiozero import InputDevice

# Setup logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# GPIO pins
LIGHT_PIN = 17
TEMP_PIN = 4

# Initialize GPIO pins
def setup_gpio():
    try:
        light_sensor = InputDevice(LIGHT_PIN, pull_up=False)
        temp_sensor = InputDevice(TEMP_PIN, pull_up=False)
        logging.info("GPIO initialized successfully.")
        return light_sensor, temp_sensor
    except Exception as e:
        logging.error(f"Failed to initialize GPIO: {e}")
        return None, None

# Simulate sensor readings
def simulate_light_sensor(light_sensor):
    try:
        current_time = datetime.datetime.now()
        if 6 <= current_time.hour < 18:
            return random.randint(600, 1000)
        else:
            return random.randint(100, 300)
    except Exception as e:
        logging.error(f"Failed to simulate light sensor: {e}")
        return 0

def simulate_temp_sensor(temp_sensor):
    try:
        return random.randint(20, 30)
    except Exception as e:
        logging.error(f"Failed to simulate temperature sensor: {e}")
        return 0

def simulate_voltage_current(light_sensor):
    try:
        if simulate_light_sensor(light_sensor) > 300:
            return (random.uniform(11.5, 12.5), random.uniform(1.5, 2.5))
        else:
            return (random.uniform(10.0, 11.0), random.uniform(0.5, 1.0))
    except Exception as e:
        logging.error(f"Failed to simulate voltage/current: {e}")
        return (0, 0)

# Read Raspberry Pi's internal temperature
def read_pi_temp():
    try:
        result = subprocess.run(['vcgencmd', 'measure_temp'], stdout=subprocess.PIPE, timeout=5)
        if result.returncode == 0:
            temp_str = result.stdout.decode('utf-8').strip().split('=')[1].strip("'")
            return float(temp_str)
        else:
            logging.warning("vcgencmd measure_temp failed or is missing.")
            return None
    except Exception as e:
        logging.error(f"Failed to read Pi temperature: {e}")
        return None

# Logging function
def log_cycle(light, temp, voltage, current, pi_temp):
    logging.info(f"Light: {light} lux, Temp: {temp}°C, Voltage: {voltage}V, Current: {current}A, Pi Temp: {pi_temp}°C")

# Main function
def main():
    light_sensor, temp_sensor = setup_gpio()
    if light_sensor is None or temp_sensor is None:
        logging.error("GPIO setup failed.")
        return

    try:
        while True:
            light = simulate_light_sensor(light_sensor)
            temp = simulate_temp_sensor(temp_sensor)
            voltage, current = simulate_voltage_current(light_sensor)
            pi_temp = read_pi_temp()

            log_cycle(light, temp, voltage, current, pi_temp)

            if light < 300:
                logging.warning("Possible solar panel performance issues.")
            if temp > 35:
                logging.warning("Simulated cooling-system activation.")
            if pi_temp is not None and pi_temp > 75:
                logging.critical("Simulated system shutdown due to high internal temperature.")

            time.sleep(5)

    except KeyboardInterrupt:
        logging.info("Program interrupted by user.")

    finally:
        if light_sensor:
            light_sensor.close()
        if temp_sensor:
            temp_sensor.close()

if __name__ == '__main__':
    main()

