import smbus
import time
import logging
from statistics import median
from math import pow

# Set up logging
logging.basicConfig(level=logging.INFO)

# BMP280 constants
BMP280_ADDRESS = 0x76
BMP280_CHIP_ID = 0xD0
BMP280_SEA_LEVEL_PRESSURE = 1013.25  # hPa

# I2C bus
bus = smbus.SMBus(1)

# BMP280 calibration data
calibration_data = {}

def read_calibration_data():
    global calibration_data
    try:
        for register in range(BMP280_CHIP_ID, BMP280_CHIP_ID + 24):
            calibration_data[register] = bus.read_byte_data(BMP280_ADDRESS, register)
    except OSError as e:
        logging.error(f"Failed to read calibration data: {e}")
        return False
    return True

def read_pressure():
    try:
        raw_pressure = bus.read_i2c_block_data(BMP280_ADDRESS, 0xF7, 3)
        pressure = (raw_pressure[0] << 12) | (raw_pressure[1] << 4) | (raw_pressure[2] >> 4)
        pressure = pressure / 100.0
        return pressure
    except OSError as e:
        logging.error(f"Failed to read pressure: {e}")
        return None

def calculate_altitude(pressure, baseline):
    return 44330 * (1 - pow(pressure / baseline, 0.190284))

def main():
    if not read_calibration_data():
        logging.error("Failed to read calibration data. Falling back to default sea level pressure.")
        baseline = BMP280_SEA_LEVEL_PRESSURE
    else:
        logging.info("Calibration data read successfully.")
        samples = []
        for _ in range(100):
            pressure = read_pressure()
            if pressure is not None:
                samples.append(pressure)
            else:
                logging.error("Failed to read pressure sample. Falling back to default sea level pressure.")
                break
        if samples:
            samples.sort()
            baseline = median(samples[25:-25])
            logging.info(f"Baseline pressure established: {baseline} hPa")
        else:
            logging.error("Failed to establish baseline pressure. Falling back to default sea level pressure.")
            baseline = BMP280_SEA_LEVEL_PRESSURE

    try:
        while True:
            pressure = read_pressure()
            if pressure is not None:
                altitude = calculate_altitude(pressure, baseline)
                logging.info(f"Current altitude: {altitude} meters")
            time.sleep(1)
    except KeyboardInterrupt:
        logging.info("Program interrupted by user.")
    finally:
        logging.info("Cleaning up resources.")

if __name__ == "__main__":
    main()

