import time
import logging
import sys
import socket
from gpiozero import DigitalInputDevice, DigitalOutputDevice
from threading import Thread
from datetime import datetime

# Setup logging
logging.basicConfig(level=logging.INFO)

# GPIO setup
data_pin = DigitalInputDevice(4, pull_up=True)
led_pin = DigitalOutputDevice(17)

# Function to read DHT22 sensor
def read_dht22():
    data = []
    try:
        data_pin.value = False
        time.sleep(0.02)
        data_pin.value = True
        time.sleep(0.00004)
        data_pin.value = False

        for _ in range(40):
            start = time.time()
            while data_pin.value == False:
                if time.time() - start > 0.0002:
                    return (25.0, 50.0)
            start = time.time()
            while data_pin.value == True:
                if time.time() - start > 0.0002:
                    return (25.0, 50.0)
            duration = time.time() - start
            if duration < 0.000026:
                data.append(0)
            elif duration < 0.000070:
                data.append(1)
            else:
                return (25.0, 50.0)

        humidity = (data[0] << 8) | data[1]
        temperature = (data[2] << 8) | data[3]
        checksum = (data[4] << 8) | data[5]
        if checksum != ((humidity >> 8) + (humidity & 0xFF) + (temperature >> 8) + (temperature & 0xFF)):
            return (25.0, 50.0)

        temperature = temperature / 10.0
        if temperature < -40:
            temperature = -40
        elif temperature > 80:
            temperature = 80

        humidity = humidity / 10.0
        if humidity < 0:
            humidity = 0
        elif humidity > 100:
            humidity = 100

        return (temperature, humidity)

    except Exception as e:
        logging.error(f"Error reading DHT22: {e}")
        return (25.0, 50.0)

# Function to control LED based on temperature
def control_led(temperature):
    if temperature > 30.0:
        led_pin.value = False
        return "ON"
    elif temperature < 27.0:
        led_pin.value = True
        return "OFF"
    else:
        return "NO_CHANGE"

# Function to send data over TCP
def send_data(temperature, humidity):
    try:
        with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
            s.connect(('192.168.1.100', 12345))
            s.sendall(f"{temperature:.1f},{humidity:.1f}".encode())
            s.close()
    except Exception as e:
        logging.error(f"Error sending data: {e}")

# Main loop
def main():
    try:
        while True:
            temperature, humidity = read_dht22()
            led_state = control_led(temperature)
            send_data(temperature, humidity)
            logging.info(f"{datetime.now()}: Temperature: {temperature:.1f}°C, Humidity: {humidity:.1f}%, LED: {led_state}")
            time.sleep(5)

    except KeyboardInterrupt:
        logging.info("Ctrl+C detected, cleaning up GPIO and exiting.")
        led_pin.value = True
        data_pin.close()
        led_pin.close()
        sys.exit(0)

if __name__ == "__main__":
    main()

