import csv
import datetime
import serial
import sys
import time
from typing import Optional

SERIAL_PORT = "/dev/ttyACM0"
SERIAL_BAUDRATE = 115200
SERIAL_TIMEOUT = 1  # seconds
LOG_FILE = "temperature_log.csv"

def celsius_to_fahrenheit(celsius: float) -> float:
    return celsius * 9/5 + 32

def read_temperature_data() -> Optional[str]:
    try:
        with serial.Serial(SERIAL_PORT, SERIAL_BAUDRATE, timeout=SERIAL_TIMEOUT) as ser:
            line = ser.readline().decode().strip()
            if line:
                return line
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        sys.exit(1)

def append_to_log(timestamp: str, celsius: float, fahrenheit: float):
    with open(LOG_FILE, 'a', newline='') as log_file:
        log_writer = csv.writer(log_file)
        if not log_file.tell():
            log_writer.writerow(["timestamp", "celsius", "fahrenheit"])
        log_writer.writerow([timestamp, celsius, fahrenheit])

def main():
    try:
        while True:
            temperature_data = read_temperature_data()
            if temperature_data:
                try:
                    celsius = float(temperature_data)
                    fahrenheit = celsius_to_fahrenheit(celsius)
                    timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                    append_to_log(timestamp, celsius, fahrenheit)
                except ValueError:
                    print(f"Warning: Invalid temperature data '{temperature_data}'. Skipping...", file=sys.stderr)
            time.sleep(1)  # Wait for 1 second before the next read
    except KeyboardInterrupt:
        print("Exiting...")
    finally:
        print("Serial port closed.")

if __name__ == "__main__":
    main()

