import smbus2
import time
import logging
import sys
import signal

class DHT20Sensor:
    def __init__(self, bus_number=1, address=0x38):
        self.bus = None
        self.bus_number = bus_number
        self.address = address
        self.last_read = 0
        self.temperature = None
        self.humidity = None
        self.failed_attempts = 0

    def _log_error(self, message):
        logging.error(f"DHT20 Sensor Error: {message}")

    def _log_warning(self, message):
        logging.warning(f"DHT20 Sensor Warning: {message}")

    def _crc8(self, data):
        crc = 0xFF
        for byte in data:
            for i in range(8):
                if (crc ^ byte) & 0x80:
                    crc = (crc << 1) ^ 0x31
                else:
                    crc = (crc << 1)
                byte = byte << 1
        return crc & 0xFF

    def _read_data(self):
        try:
            self.bus.write_i2c_block_data(self.address, 0xAC, [0x33, 0x00])
            for _ in range(10):
                status = self.bus.read_byte(self.address, 0x71)
                if status & 0x80 == 0:
                    break
                time.sleep(0.08)
            else:
                self._log_error("Measurement timeout")
                return None

            data = self.bus.read_i2c_block_data(self.address, 0x71, 7)
            if self._crc8(data[:6]) != data[6]:
                self._log_warning("CRC check failed")
                return None

            humidity_raw = ((data[1] << 12) | (data[2] << 4) | ((data[3] & 0xF0) >> 4))
            humidity = humidity_raw / (2**20) * 100

            temperature_raw = (((data[3] & 0x0F) << 16) | (data[4] << 8) | data[5])
            temperature = temperature_raw / (2**19) * 200 - 50

            return humidity, temperature

        except OSError as e:
            self._log_error(f"I2C error: {e}")
            return None

    def begin(self):
        try:
            self.bus = smbus2.SMBus(self.bus_number)
            time.sleep(0.5)
            status = self.bus.read_byte(self.address, 0x71)
            if (status & 0x18) != 0x18:
                self._log_error("Status check failed")
                return False
            return True

        except OSError as e:
            self._log_error(f"Bus open error: {e}")
            return False

    def get_temperature_and_humidity(self):
        current_time = time.time()
        if current_time - self.last_read < 2:
            return self.humidity, self.temperature, False

        while self.failed_attempts < 5:
            result = self._read_data()
            if result:
                self.humidity, self.temperature = result
                self.last_read = current_time
                self.failed_attempts = 0
                return self.humidity, self.temperature, False
            else:
                self.failed_attempts += 1
                time.sleep(0.01)

        return None, None, True

    def close(self):
        if self.bus:
            self.bus.close()
            self.bus = None

    def __enter__(self):
        if not self.begin():
            raise RuntimeError("Failed to initialize DHT20 sensor")
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        self.close()

def signal_handler(sig, frame):
    print("KeyboardInterrupt or SystemExit caught, exiting gracefully.")
    sys.exit(0)

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

if __name__ == "__main__":
    try:
        with DHT20Sensor() as sensor:
            while True:
                humidity, temperature, failed = sensor.get_temperature_and_humidity()
                if failed:
                    print("Failed to read temperature and humidity after 5 attempts.")
                    break
                print(f"Humidity: {humidity}%, Temperature: {temperature}°C")
                time.sleep(2)

    except Exception as e:
        print(f"An error occurred: {e}")
        sys.exit(0)

