                    format='%(asctime)s - %(levelname)s - %(message)s')

# GPIO pins for DHT22 sensors
sensor1_pin = 4
sensor2_pin = 17

# Retry mechanism for DHT22 readings
def read_dht22(pin, retries=3):
    for attempt in range(retries):
        try:
            sensor = DHT22(pin)
            humidity, temperature = sensor.read()
            if humidity is not None and temperature is not None:
                return humidity, temperature
            else:
                logging.error(f"Failed to read DHT22 on pin {pin} (Attempt {attempt + 1}/{retries})")
                time.sleep(2)
        except Exception as e:
            logging.error(f"Error reading DHT22 on pin {pin} (Attempt {attempt + 1}/{retries}): {str(e)}")
            time.sleep(2)
    return None, None

# Signal handler for graceful exit
def signal_handler(sig, frame):
    logging.info("KeyboardInterrupt caught, exiting gracefully.")
    sys.exit(0)

signal.signal(signal.SIGINT, signal_handler)

# Main loop
try:
    while True:
        humidity1, temperature1 = read_dht22(sensor1_pin)
        humidity2, temperature2 = read_dht22(sensor2_pin)

        if humidity1 is not None and temperature1 is not None:
            if temperature1 < 5 or temperature1 > 35:
                logging.error(f"Temperature anomaly on pin {sensor1_pin}: {temperature1}°C")
