    fan = PWMOutputDevice(14, pin_factory=factory)
except Exception as e:
    print(f"Error initializing PWMOutputDevice: {e}")
    fan = None

# Function to parse CPU temperature from vcgencmd
def get_cpu_temp():
    try:
        result = subprocess.check_output(['vcgencmd', 'measure_temp']).decode('utf-8')
        temp_c = float(result.replace("temp=", "").replace("'C\n", ""))
        return temp_c
    except Exception as e:
        print(f"Error reading CPU temperature: {e}")
        return None

# Function to set fan duty cycle based on temperature
def set_fan_duty_cycle(temp):
    if fan is None:
        print("PWMOutputDevice not initialized, skipping fan control.")
        return

    if temp is None:
        print("CPU temperature not available, keeping last known fan speed.")
        return

    if temp > 70:
        fan.duty_cycle = 1.0
    elif temp > 60:
        fan.duty_cycle = 0.85
    elif temp > 50:
        fan.duty_cycle = 0.7
    elif temp > 40:
        fan.duty_cycle = 0.5
    elif temp > 32:
        fan.duty_cycle = 0.25
    elif temp > 25:
        fan.duty_cycle = 0.15
    else:
        fan.duty_cycle = 0.0

    print(f"Set fan duty cycle to {fan.duty_cycle * 100}% for temperature {temp}°C")

# Signal handler for SIGINT and SIGTERM
def signal_handler(sig, frame):
    if fan is not None:
        fan.close()
    print("Exiting...")
    exit(0)

# Register signal handlers
signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

# Main loop
while True:
    temp = get_cpu_temp()
    set_fan_duty_cycle(temp)
    time.sleep(5)

