import argparse
import signal
import sys
import time
import RPi.GPIO as GPIO
from threading import Thread

# Define GPIO pin for the dog
DOG_PIN = 18

# Initialize GPIO
GPIO.setmode(GPIO.BCM)
GPIO.setup(DOG_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)

# Global variables
log_file = None
receive_thread = None

def signal_handler(signal, frame):
    global receive_thread
    if receive_thread:
        receive_thread.stop()
    GPIO.cleanup()
    sys.exit(0)

def start_server(filename):
    global log_file, receive_thread
    try:
        log_file = open(filename, "w")
        receive_thread = ReceiveThread()
        receive_thread.start()
        print(f"Server started, logging to {filename}")
    except Exception as e:
        print(f"Error starting server: {e}")

def stop_server():
    global receive_thread
    if receive_thread:
        receive_thread.stop()
        receive_thread.join()
        print("Server stopped")

def display_log():
    global log_file
    if log_file:
        print(log_file.read())
    else:
        print("No log file open")

def send_data(data):
    global log_file
    if log_file:
        log_file.write(f"{data}\n")
        print(f"Sent: {data}")
    else:
        print("No log file open")

def write_data(data):
    global log_file
    if log_file:
        log_file.write(f"{data}\n")
        print(f"Written: {data}")
    else:
        print("No log file open")

def help_command(command=None):
    if command == "start":
        print("start <filename>: Creates a log file and starts the logging thread.")
    elif command == "stop":
        print("stop: Stops the server and the receive thread.")
    elif command == "display":
        print("display: Prints the contents of the log file.")
    elif command == "send":
        print("send <data>: Sends data using DOG.send().")
    elif command == "write":
        print("write <data>: Writes data directly to the log file with a newline character.")
    elif command == "exit":
        print("exit: Stops the server, cleans up GPIO, and exits.")
    else:
        print("start <filename> - Creates a log file and starts the logging thread.")
        print("stop - Stops the server and the receive thread.")
        print("display - Prints the contents of the log file.")
        print("send <data> - Sends data using DOG.send().")
        print("write <data> - Writes data directly to the log file with a newline character.")
        print("exit - Stops the server, cleans up GPIO, and exits.")

class ReceiveThread(Thread):
    def __init__(self):
        super().__init__()
        self._stop_event = False

    def run(self):
        while not self._stop_event:
            if GPIO.input(DOG_PIN) == GPIO.LOW:
                print("Received data")
                if log_file:
                    log_file.write("\nReceived data\n")
            time.sleep(0.1)

    def stop(self):
        self._stop_event = True

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("command", choices=["start", "stop", "display", "send", "write", "help", "exit"])
    parser.add_argument("data", nargs="?", default=None)
    args = parser.parse_args()

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    if args.command == "start":
        start_server(args.data)
    elif args.command == "stop":
        stop_server()
    elif args.command == "display":
        display_log()
    elif args.command == "send":
        send_data(args.data)
    elif args.command == "write":
        write_data(args.data)
    elif args.command == "help":
        help_command(args.data)
    elif args.command == "exit":
        stop_server()
        GPIO.cleanup()
        sys.exit(0)

if __name__ == "__main__":
    main()
```

This script sets up a command-line server for a Raspberry Pi using RPi.GPIO. It manages a background receive thread that polls the GPIO pin every 0.1 seconds. The server implements various commands for starting/stopping the server, displaying the log file, sending data, writing data directly to the log file, and exiting. It also includes a signal handler to ensure GPIO cleanup on all exit paths.

