# Function to handle graceful shutdown on KeyboardInterrupt
def signal_handler(sig, frame):
    print("Gracefully shutting down...")
    try:
        output.close()
    except Exception as e:
        print(f"Error while closing GPIO: {e}")
    sys.exit(0)

# Function to handle general exceptions
def general_exception_handler(func):
    def wrapper(*args, **kwargs):
        try:
            return func(*args, **kwargs)
        except Exception as e:
            print(f"An error occurred: {e}")
            sys.exit(1)
    return wrapper

# Set up GPIO pin
@general_exception_handler
def setup_gpio():
    output = DigitalOutputDevice(17, active_high=True)
    return output

# Main function
def main():
    try:
        # Register signal handler for KeyboardInterrupt
        signal.signal(signal.SIGINT, signal_handler)

        # Setup GPIO
        output = setup_gpio()

        # Repeat pulse indefinitely
        while True:
            output.on()
            time.sleep(0.1)
            output.off()
            time.sleep(0.1)

    except Exception as e:
        print(f"An unexpected error occurred: {e}")
        sys.exit(1)

if __name__ == "__main__":
    main()

