import logging
import signal
import time
import zmq
from gpiozero import PWMOutputDevice, OutputDevice

class PIDHandler:
    def __init__(self, pwm=False):
        self.logger = logging.getLogger(__name__)
        self.last_msg = time.time()
        self.global_err_state = False
        self.pwm_device = None
        self.digital_device = None

        try:
            if pwm:
                self.pwm_device = PWMOutputDevice(12, frequency=1000)
            else:
                self.digital_device = OutputDevice(10)
        except Exception as e:
            self.logger.error(f"Failed to initialize GPIO: {e}")
            raise

        self.signal_handler = signal.signal(signal.SIGINT, self.cleanup)
        self.signal_handler = signal.signal(signal.SIGTERM, self.cleanup)

    def cleanup(self, signum, frame):
        self.set_error_output(False)
        if self.pwm_device:
            self.pwm_device.close()
        if self.digital_device:
            self.digital_device.close()

    def update_error_output(self):
        if self.pwm_device:
            if self.global_err_state:
                self.pwm_device.duty_cycle = 1.0
            else:
                self.pwm_device.duty_cycle = 0.0
        elif self.digital_device:
            if self.global_err_state:
                self.digital_device.on()
            else:
                self.digital_device.off()

    def set_error_output(self, state: bool):
        self.global_err_state = state
        self.update_error_output()

    def handle_message(self, context, socket):
        try:
            message = socket.recv(zmq.NOBLOCK)
            if message:
                self.last_msg = time.time()
                # Process subscription callbacks here
                pass
        except zmq.Again:
            if time.time() - self.last_msg > 20:
                self.set_error_output(True)

