import pigpio
from typing import Union

class OutputPin:
    def __init__(self, pin_number: int, initial_value: int):
        self.pin_number = pin_number
        self.initial_value = initial_value
        self.pi = self._connect_to_pigpio()
        self._setup_pin()
        self._write_initial_value()

    def _connect_to_pigpio(self) -> pigpio.pi:
        try:
            pi = pigpio.pi()
            if not pi.connected:
                raise ConnectionError("Failed to connect to pigpio daemon.")
            return pi
        except Exception as e:
            raise Exception("Failed to connect to pigpio daemon: " + str(e))

    def _setup_pin(self):
        try:
            self.pi.set_mode(self.pin_number, pigpio.OUTPUT)
        except Exception as e:
            raise Exception("Failed to set pin mode: " + str(e))

    def _write_initial_value(self):
        try:
            self.pi.write(self.pin_number, self.initial_value)
        except Exception as e:
            raise Exception("Failed to write initial value: " + str(e))

    def set_value(self, value: int):
        if value not in [0, 1]:
            raise ValueError("Value must be 0 or 1.")
        try:
            self.pi.write(self.pin_number, value)
        except Exception as e:
            raise Exception("Failed to set pin value: " + str(e))

    def shutdown(self):
        try:
            self.pi.set_mode(self.pin_number, pigpio.INPUT)
        except Exception as e:
            print("Failed to set pin mode back to INPUT: " + str(e))
        finally:
            self.pi.stop()

if __name__ == '__main__':
    try:
        pin = OutputPin(17, 0)
        import time
        for _ in range(10):
            pin.set_value(1)
            time.sleep(0.5)
            pin.set_value(0)
            time.sleep(0.5)
        pin.shutdown()
    except Exception as e:
        print("An error occurred: " + str(e))

