import RPi.GPIO as GPIO
import time
import json
import threading
import socket
import math
import logging
import signal
from gpiozero import PWMLED
from paho.mqtt.client import Client

# Setup logging
logging.basicConfig(filename='notification_light.log', level=logging.INFO)

# GPIO setup
GPIO.setmode(GPIO.BCM)
GPIO_PINS = {
    'LED1': {'red': 17, 'green': 18, 'blue': 27},
    'LED2': {'red': 22, 'green': 23, 'blue': 24},
    'LED3': {'red': 5, 'green': 6, 'blue': 13}
}

# PWM setup
PWM_FREQUENCY = 1000
PWM_LEDs = {pin: PWMLED(pin, active_high=False) for pin in GPIO_PINS.values()}
for led in PWM_LEDs.values():
    led.frequency = PWM_FREQUENCY

# Socket setup
TCP_HOST = '192.168.1.100'
TCP_PORT = 5000

# Exponential backoff for reconnection
BACKOFF_BASE = 1
BACKOFF_MAX = 60
BACKOFF_FACTOR = 2

# Non-linear mapping function
def map_value(value, min_val, mid_val, max_val):
    if value < min_val:
        return 0
    elif value > max_val:
        return 1
    elif value < mid_val:
        return (value - min_val) / (mid_val - min_val)
    else:
        return 1 - ((value - mid_val) / (max_val - mid_val))

# Thread to update PWM duty cycles
class UpdatePWMThread(threading.Thread):
    def __init__(self):
        super().__init__()
        self.lock = threading.Lock()
        self.running = True

    def run(self):
        while self.running:
            try:
                with self.lock:
                    data = sock.recv(1024)
                    if data:
                        try:
                            message = json.loads(data)
                            cpu_usage = message.get('cpu_usage', 0)
                            memory_usage = message.get('memory_usage', 0)
                            disk_io = message.get('disk_io', 0)

                            if 0 <= cpu_usage <= 100 and 0 <= memory_usage <= 100 and 0 <= disk_io <= 100:
                                cpu_map = map_value(cpu_usage, 33, 66, 100)
                                mem_map = map_value(memory_usage, 33, 66, 100)
                                disk_map = map_value(disk_io, 33, 66, 100)

                                for led, map_val in zip(PWM_LEDs.values(), [cpu_map, mem_map, disk_map]):
                                    led.value = map_val
                            else:
                                logging.info("Invalid reading received: %s", message)
                        except json.JSONDecodeError:
                            logging.info("Invalid JSON message received: %s", data)
            except socket.error as e:
                logging.info("Socket error: %s", e)
                time.sleep(BACKOFF_BASE)
                BACKOFF_BASE = min(BACKOFF_BASE * BACKOFF_FACTOR, BACKOFF_MAX)
            except Exception as e:
                logging.error("Unexpected error: %s", e)

# Signal handler
def signal_handler(sig, frame):
    logging.info("Received signal %d, stopping PWM and cleaning up...", sig)
    with threading.Lock():
        for led in PWM_LEDs.values():
            led.value = 0
        GPIO.cleanup()
        sock.close()
        update_thread.join()
        logging.info("Cleaned up successfully.")
        sys.exit(0)

# Main function
def main():
    global sock, update_thread

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        sock.connect((TCP_HOST, TCP_PORT))
        logging.info("Connected to %s:%d", TCP_HOST, TCP_PORT)

        update_thread = UpdatePWMThread()
        update_thread.start()

        while True:
            time.sleep(1)

    except socket.error as e:
        logging.error("Failed to connect to %s:%d: %s", TCP_HOST, TCP_PORT, e)

if __name__ == "__main__":
    main()

