        color_sensor.set_gain(TCS34725.GAIN_ONE)
        color_sensor.set_integration_time(TCS34725.INTEGRATIONTIME_240MS)
        color_sensor.set_interrupt_mode(TCS34725.INTERRUPT_MODE_NONE)
