import random
import time
import gpiozero

class AmbientLightSensor:
    def __init__(self, led_pin):
        self.led = gpiozero.LED(led_pin)

    def simulate_light_level(self):
        light_level = random.randint(0, 100)
        percentage = f"{light_level}%"
        if light_level < 50:
            self.led.on()
            status = "ON"
        else:
            self.led.off()
            status = "OFF"
        return percentage, status

    def run_simulation(self, cycles, delay):
        try:
            for _ in range(cycles):
                percentage, status = self.simulate_light_level()
                print(f"Simulated Light Level: {percentage}, LED Status: {status}")
                time.sleep(delay)
        except KeyboardInterrupt:
            print("\nSimulation interrupted by user.")
        finally:
            self.led.off()
            print("LED turned off and GPIO resources released.")

if __name__ == "__main__":
    with gpiozero.OutputDevice(17):
        sensor = AmbientLightSensor(17)
        sensor.run_simulation(cycles=5, delay=2)

import atexit
import signal
import logging
import Adafruit_MotorHAT
import Adafruit_PCA9685
import time

# Set up logging
logging.basicConfig(level=logging.INFO)

class DCMotorHATExtra(Adafruit_MotorHAT):
    def __init__(self, addr=0x60, busnum=1, freq=60):
        self.addr = addr
        self.busnum = busnum
        self.freq = freq
        self.pwm = Adafruit_PCA9685.PCA9685(self.addr, self.busnum)
        self.pwm.set_pwm_freq(self.freq)
        self.motors = [None] * 4

        try:
            self.verify_i2c()
        except Exception as e:
            logging.error(f"Failed to initialize I2C: {e}")
            raise

        atexit.register(self.release_all_motors)
        signal.signal(signal.SIGINT, self.handle_signal)
        signal.signal(signal.SIGTERM, self.handle_signal)

    def verify_i2c(self):
        try:
            self.pwm.set_pwm(0, 0, 0)
        except Exception as e:
            logging.error(f"I2C verification failed: {e}")
            raise

    def set_pwm_freq(self, freq):
        self.freq = freq
        self.pwm.set_pwm_freq(freq)

    def get_pwm_freq(self):
        return self.freq

    def release_all_motors(self):
        for motor in self.motors:
            if motor:
                motor.stop()

    def handle_signal(self, signum, frame):
        logging.info("Received signal, stopping motors and exiting.")
        self.release_all_motors()
        exit(0)

class DCMotor:
    def __init__(self, hat: DCMotorHATExtra, motor_num: int, freq=None, invert=False):
        if motor_num < 1 or motor_num > 4:
            raise ValueError("Motor number must be between 1 and 4.")
        self.hat = hat
        self.motor_num = motor_num
        self.freq = freq if freq else hat.get_pwm_freq()
        self.invert = invert
        self.last_duty_cycle = 0
        self.motor = hat.getMotor(motor_num)

    def set_dc(self, duty_cycle):
        if duty_cycle == 0:
            self.stop()
            return

        duty_cycle = max(-255, min(255, duty_cycle))
        direction = Adafruit_MotorHAT.FORWARD if (duty_cycle > 0) ^ self.invert else Adafruit_MotorHAT.BACKWARD
        speed = abs(duty_cycle)

        try:
            self.motor.setSpeed(speed)
            self.motor.run(direction)
            self.last_duty_cycle = duty_cycle
        except Exception as e:
            logging.error(f"Failed to set duty cycle for motor {self.motor_num}: {e}")

    def stop(self):
        try:
            self.motor.run(Adafruit_MotorHAT.RELEASE)
        except Exception as e:
            logging.error(f"Failed to stop motor {self.motor_num}: {e}")

    def close(self):
        self.stop()

    def get_status(self):
        return {
            "motor_num": self.motor_num,
            "freq": self.freq,
            "invert": self.invert,
            "last_duty_cycle": self.last_duty_cycle
        }

# Usage example
if __name__ == "__main__":
    try:
        hat = DCMotorHATExtra()
        motor = DCMotor(hat, 1)

        # Ramp motor forward and backward
        for duty_cycle in range(-255, 256, 50):
            motor.set_dc(duty_cycle)
            time.sleep(1)

        motor.stop()
        hat.close()
    except Exception as e:
        logging.error(f"An error occurred: {e}")

