    if direction == "forward":
        GPIO.output(FORWARD_PIN, GPIO.HIGH)
        GPIO.output(REVERSE_PIN, GPIO.LOW)
    elif direction == "reverse":
        GPIO.output(FORWARD_PIN, GPIO.LOW)
        GPIO.output(REVERSE_PIN, GPIO.HIGH)
    else:
        raise ValueError("Invalid direction. Must be 'forward' or 'reverse'.")

# Ramp speed
def ramp_speed(direction, start_duty=0, end_duty=80, step_delay=0.03):
    if direction == "forward":
        for duty in range(start_duty, end_duty + 1, 1):
            pwm.ChangeDutyCycle(duty)
            time.sleep(step_delay)
    elif direction == "reverse":
        for duty in range(start_duty, end_duty + 1, 1):
            pwm.ChangeDutyCycle(duty)
            time.sleep(step_delay)
    else:
        raise ValueError("Invalid direction. Must be 'forward' or 'reverse'.")

