import pigpio
from typing import Union

class MotorError(Exception):
    """Custom exception for motor control errors."""
    pass

class Motor:
    def __init__(self, pi: pigpio.pi, pin: int):
        if not isinstance(pi, pigpio.pi):
            raise MotorError("Invalid or disconnected pigpio.pi instance.")

        self.pi = pi
        self.pin = pin
        self.pi.set_mode(self.pin, pigpio.OUTPUT)
        self.pi.set_PWM_frequency(self.pin, 1000)
        self.pi.set_PWM_dutycycle(self.pin, 0)

    def set_frequency(self, freq: int) -> None:
        if not isinstance(freq, int) or freq <= 0:
            raise MotorError("Frequency must be a positive integer.")

        if self.pi.set_PWM_frequency(self.pin, freq) != pigpio.PI_BAD_OPTION:
            raise MotorError("Failed to set PWM frequency.")

    def set_duty_cycle(self, duty: int) -> None:
        if not isinstance(duty, int) or duty < 0 or duty > 255:
            raise MotorError("Duty cycle must be an integer in the range 0-255.")

        if self.pi.set_PWM_dutycycle(self.pin, duty) != pigpio.PI_BAD_OPTION:
            raise MotorError("Failed to set PWM duty cycle.")

    def stop(self) -> None:
        self.set_duty_cycle(0)

    def close(self) -> None:
        self.stop()
        self.pi.set_PWM_frequency(self.pin, 0)
        self.pi.set_mode(self.pin, pigpio.INPUT)

    def __del__(self):
        self.close()

