import RPi.GPIO as GPIO
import time
import logging

class ServoController:
    def __init__(self, pin):
        self.pin = pin
        self.frequency = 50  # Hz
        self.duty_cycle_min = 2.5 / 100  # 2.5%
        self.duty_cycle_max = 12.5 / 100  # 12.5%
        self.angle_to_duty_cycle = {
            0: self._angle_to_duty_cycle(0),
            45: self._angle_to_duty_cycle(45),
            90: self._angle_to_duty_cycle(90),
            135: self._angle_to_duty_cycle(135),
            180: self._angle_to_duty_cycle(180)
        }
        self.setup_gpio()

    def setup_gpio(self):
        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(self.pin, GPIO.OUT)
            self.pwm = GPIO.PWM(self.pin, self.frequency)
            self.pwm.start(self.duty_cycle_min)
        except Exception as e:
            logging.error(f"Failed to initialize GPIO: {e}")
            self.cleanup()
            raise

    def _angle_to_duty_cycle(self, angle):
        return self.duty_cycle_min + (angle / 180) * (self.duty_cycle_max - self.duty_cycle_min)

    def move_to(self, angle):
        try:
            duty_cycle = self.angle_to_duty_cycle[angle]
            self.pwm.ChangeDutyCycle(duty_cycle)
            logging.info(f"Moved servo to {angle} degrees")
            time.sleep(0.5)
        except KeyError:
            logging.warning(f"Invalid angle {angle} provided, skipping")

    def stop(self):
        self.pwm.stop()
        self.cleanup()

    def cleanup(self):
        GPIO.cleanup(self.pin)

def main(angles):
    try:
        servo = ServoController(18)
        for angle in angles:
            servo.move_to(angle)
        servo.stop()
    except KeyboardInterrupt:
        logging.info("KeyboardInterrupt caught, stopping servo and cleaning up GPIO")
        if hasattr(servo, 'stop'):
            servo.stop()
    except Exception as e:
        logging.error(f"An error occurred: {e}")
        if hasattr(servo, 'cleanup'):
            servo.cleanup()

if __name__ == "__main__":
    logging.basicConfig(level=logging.INFO)
    main([0, 45, 90, 135, 180, 135, 90, 45, 0])

