import time
import signal
import sys
from gpiozero import AngularServo, OutputDeviceBadValue, Pin
from gpiozero.exc import PinConflict, OutputDeviceError

class RoboticArm:
    def __init__(self):
        self.base = AngularServo(Pin(17), min_pulse_width=0.5, max_pulse_width=2.5, frequency=50)
        self.shoulder = AngularServo(Pin(27), min_pulse_width=0.5, max_pulse_width=2.5, frequency=50)
        self.gripper = AngularServo(Pin(22), min_pulse_width=0.5, max_pulse_width=2.5, frequency=50)

    def move_joint(self, servo, target_angle):
        try:
            target_angle = max(-90, min(90, target_angle))
            servo.angle = target_angle
            time.sleep(0.4)
        except OutputDeviceBadValue:
            print(f"Invalid angle {target_angle} for servo {servo}")
        except PinConflict:
            print("Pin conflict detected.")
        except RuntimeError:
            print("GPIO allocation failed.")

    def go_to_pose(self, base_angle, shoulder_angle, gripper_angle):
        self.move_joint(self.base, base_angle)
        self.move_joint(self.shoulder, shoulder_angle)
        self.move_joint(self.gripper, gripper_angle)

    def release(self):
        self.base.angle = None
        self.shoulder.angle = None
        self.gripper.angle = None

def run_demo_sequence(robot_arm):
    poses = [(0, 0, 0), (45, -30, 20), (-45, 30, -20), (0, 0, 0)]
    for pose in poses:
        print(f"Moving to pose: {pose}")
        robot_arm.go_to_pose(*pose)
        time.sleep(1)

def signal_handler(sig, frame):
    print("Cleaning up GPIO resources...")
    robot_arm.release()
    sys.exit(0)

if __name__ == "__main__":
    try:
        robot_arm = RoboticArm()
        signal.signal(signal.SIGINT, signal_handler)
        signal.signal(signal.SIGTERM, signal_handler)
        run_demo_sequence(robot_arm)
    except Exception as e:
        print(f"An error occurred: {e}")
        robot_arm.release()

import serial
