import signal
import logging

class Servo:
    def __init__(self, port='/dev/serial0', baudrate=115200):
        self.port = port
        self.baudrate = baudrate
        self.client = None
        self.register_map = {
            'CONTROL': {
                'R/W': 'W',
                'Register': 0x3100,
                'functioncode': 6,
                'Value': {
                    'Stop': 0x0006,
                    'Start': 0x000F
                }
            },
            'STATUS': {
                'R/W': 'R',
                'Register': 0x3000,
                'functioncode': 3
            },
            'OPMODE': {
                'R/W': 'W',
                'Register': 0x3500,
                'functioncode': 6,
                'Value': {
                    'Position': 1
                }
            },
            'VelocityCommand': {
                'R/W': 'W',
                'Register': 0x6F00,
                'functioncode': 16
            },
            'VelocityFeedback': {
                'R/W': 'R',
                'Register': 0x3B00,
                'functioncode': 3,
                'read_length': 2
            },
            'PositionCommand': {
                'R/W': 'W',
                'Register': 0x4000,
                'functioncode': 16
            },
            'PositionFeedback': {
                'R/W': 'R',
                'Register': 0x3700,
                'functioncode': 3,
                'read_length': 2
            }
        }

        self.setup_signal_handlers()

    def setup_signal_handlers(self):
        def signal_handler(sig, frame):
            self.close()
            logging.info("Exiting gracefully due to signal.")
            exit(0)

        signal.signal(signal.SIGINT, signal_handler)
        signal.signal(signal.SIGTERM, signal_handler)

    def connect(self):
        try:
            self.client = ModbusSerialClient(method='rtu', port=self.port, baudrate=self.baudrate)
            self.client.connect()
            logging.info("Connected to Modbus RTU device.")
        except serial.SerialException as e:
            logging.warning("Serial port not found or unable to connect: %s", e)
            self.client = None

    def close(self):
        if self.client:
            self.client.close()
            logging.info("Disconnected from Modbus RTU device.")

    def write_register(self, register_name, value):
        if not self.client:
            logging.warning("Not connected to Modbus device.")
            return

        try:
            if register_name == 'CONTROL':
                self.client.write_register(self.register_map[register_name]['Register'], value)
            elif register_name == 'OPMODE':
                self.client.write_register(self.register_map[register_name]['Register'], value)
            elif register_name == 'VelocityCommand':
                self.client.write_registers(self.register_map[register_name]['Register'], [value])
            elif register_name == 'PositionCommand':
                self.client.write_registers(self.register_map[register_name]['Register'], [value])
            else:
                logging.warning("Invalid register name for write operation.")
        except ModbusException as e:
            logging.error("Error writing to register: %s", e)

    def read_register(self, register_name):
        if not self.client:
            logging.warning("Not connected to Modbus device.")
            return

        try:
            if register_name == 'STATUS':
                return self.client.read_holding_registers(self.register_map[register_name]['Register'], 1)[0]
            elif register_name == 'VelocityFeedback':
                return self.client.read_holding_registers(self.register_map[register_name]['Register'], self.register_map[register_name]['read_length'])
            elif register_name == 'PositionFeedback':
                return self.client.read_holding_registers(self.register_map[register_name]['Register'], self.register_map[register_name]['read_length'])
            else:
                logging.warning("Invalid register name for read operation.")
        except ModbusException as e:
            logging.error("Error reading from register: %s", e)

# Example usage
if __name__ == "__main__":
    servo = Servo()
    servo.connect()

    try:
        # Example write operations
        servo.write_register('CONTROL', servo.register_map['CONTROL']['Value']['Start'])
        servo.write_register('OPMODE', servo.register_map['OPMODE']['Value']['Position'])

        # Example read operations
        status = servo.read_register('STATUS')
        velocity_feedback = servo.read_register('VelocityFeedback')
        position_feedback = servo.read_register('PositionFeedback')

        logging.info("Status: %s", status)
        logging.info("Velocity Feedback: %s", velocity_feedback)
        logging.info("Position Feedback: %s", position_feedback)

    finally:
        servo.close()

