import serial
import minimalmodbus
import signal
import logging
import sys

class ModbusRTUServo:
    def __init__(self, port='/dev/serial0', baudrate=115200, slave_address=1):
        self.port = port
        self.baudrate = baudrate
        self.slave_address = slave_address
        self.ser = None
        self.modbus = None
        self.setup_logging()

    def setup_logging(self):
        logging.basicConfig(level=logging.INFO)

    def open_serial(self):
        try:
            self.ser = serial.Serial(self.port, self.baudrate, timeout=1)
            if not self.ser.isOpen():
                raise ValueError("Serial port is not open.")
            self.modbus = minimalmodbus.Instrument(self.ser, 1, 2, 0)
            self.modbus.serial.timeout = 1
            return True
        except (OSError, ValueError) as e:
            logging.error(f"Failed to open serial port: {e}")
            return False

    def close_serial(self):
        if self.ser:
            self.ser.close()
            self.ser = None
            self.modbus = None

    def set_operation_mode(self, mode):
        if not self.ser:
            return "Serial port is not open."
        try:
            self.modbus.write_register(0x3500, mode, 0)
            return "Operation mode set successfully."
        except minimalmodbus.ModbusException as e:
            logging.error(f"Failed to set operation mode: {e}")
            return f"Failed to set operation mode: {e}"

    def write_position_command(self, value):
        if not self.ser:
            return "Serial port is not open."
        try:
            self.modbus.write_register(0x4000, value, 0)
            return "Position command written successfully."
        except minimalmodbus.ModbusException as e:
            logging.error(f"Failed to write position command: {e}")
            return f"Failed to write position command: {e}"

    def write_velocity_command(self, value):
        if not self.ser:
            return "Serial port is not open."
        try:
            self.modbus.write_register(0x6F00, value, 0)
            return "Velocity command written successfully."
        except minimalmodbus.ModbusException as e:
            logging.error(f"Failed to write velocity command: {e}")
            return f"Failed to write velocity command: {e}"

    def read_position_feedback(self):
        if not self.ser:
            return "Serial port is not open."
        try:
            position = self.modbus.read_register(0x3700, 2)
            return position
        except minimalmodbus.ModbusException as e:
            logging.error(f"Failed to read position feedback: {e}")
            return f"Failed to read position feedback: {e}"

    def read_velocity_feedback(self):
        if not self.ser:
            return "Serial port is not open."
        try:
            velocity = self.modbus.read_register(0x3B00, 2)
            return velocity
        except minimalmodbus.ModbusException as e:
            logging.error(f"Failed to read velocity feedback: {e}")
            return f"Failed to read velocity feedback: {e}"

    def start(self):
        if not self.ser:
            return "Serial port is not open."
        try:
            self.modbus.write_register(0x3100, 0x000F, 0)
            return "Servo started successfully."
        except minimalmodbus.ModbusException as e:
            logging.error(f"Failed to start servo: {e}")
            return f"Failed to start servo: {e}"

    def stop(self):
        if not self.ser:
            return "Serial port is not open."
        try:
            self.modbus.write_register(0x3100, 0x0006, 0)
            return "Servo stopped successfully."
        except minimalmodbus.ModbusException as e:
            logging.error(f"Failed to stop servo: {e}")
            return f"Failed to stop servo: {e}"

    def read_status(self):
        if not self.ser:
            return "Serial port is not open."
        try:
            status = self.modbus.read_register(0x3000, 1)
            return status
        except minimalmodbus.ModbusException as e:
            logging.error(f"Failed to read status: {e}")
            return f"Failed to read status: {e}"

    def __enter__(self):
        if not self.open_serial():
            raise ValueError("Failed to open serial port.")
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        self.close_serial()

def signal_handler(sig, frame):
    logging.info("Received signal, shutting down...")
    sys.exit(0)

if __name__ == '__main__':
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        with ModbusRTUServo() as servo:
            logging.info("Serial port opened.")
            servo.start()
            logging.info("Servo started.")
            servo.write_position_command(1000)
            logging.info("Position command sent.")
            position = servo.read_position_feedback()
            logging.info(f"Position feedback: {position}")
            servo.stop()
            logging.info("Servo stopped.")
    except Exception as e:
        logging.error(f"An error occurred: {e}")
        sys.exit(1)
    finally:
        logging.info("Clean shutdown.")

