import smbus
from datetime import datetime
import signal

class DS1338RTC:
    def __init__(self, bus=1, address=0x68):
        self.bus = smbus.SMBus(bus)
        self.address = address
        self.verify_device()

    def verify_device(self):
        try:
            self.bus.read_byte(self.address)
        except IOError:
            raise IOError("DS1338 RTC not found at address 0x{:02X}".format(self.address))

    def read_register(self, reg):
        try:
            value = self.bus.read_byte(self.address, reg)
            return value
        except IOError as e:
            raise IOError("Failed to read register 0x{:02X}: {}".format(reg, e))

    def write_register(self, reg, value):
        try:
            self.bus.write_byte(self.address, reg, value)
        except IOError as e:
            raise IOError("Failed to write to register 0x{:02X}: {}".format(reg, e))

    def read_bcd(self, reg):
        value = self.read_register(reg)
        return (value & 0x7F) + ((value >> 4) * 10)

    def write_bcd(self, reg, value):
        value = (value // 10) * 16 + (value % 10)
        self.write_register(reg, value)

    def read_seconds(self):
        return self.read_bcd(0x00)

    def write_seconds(self, seconds):
        self.write_bcd(0x00, seconds)

    def read_minutes(self):
        return self.read_bcd(0x01)

    def write_minutes(self, minutes):
        self.write_bcd(0x01, minutes)

    def read_hours(self):
        hours = self.read_bcd(0x02)
        return hours & 0x3F  # Mask bit 6 for 24-hour format

    def write_hours(self, hours):
        self.write_bcd(0x02, hours & 0x3F)  # Clear bit 6 for 24-hour format

    def read_date(self):
        return self.read_bcd(0x04)

    def write_date(self, date):
        self.write_bcd(0x04, date)

    def read_month(self):
        return self.read_bcd(0x05)

    def write_month(self, month):
        self.write_bcd(0x05, month)

    def read_year(self):
        return self.read_bcd(0x06)

    def write_year(self, year):
        self.write_bcd(0x06, year % 100)  # Store only the two low BCD digits

    def read_datetime(self, century=21):
        seconds = self.read_seconds()
        minutes = self.read_minutes()
        hours = self.read_hours()
        date = self.read_date()
        month = self.read_month()
        year = self.read_year()
        return datetime(century * 100 + year, month, date, hours, minutes, seconds)

    def write_all(self, seconds=None, minutes=None, hours=None, date=None, month=None, year=None):
        if seconds is not None:
            self.write_seconds(seconds)
        if minutes is not None:
            self.write_minutes(minutes)
        if hours is not None:
            self.write_hours(hours)
        if date is not None:
            self.write_date(date)
        if month is not None:
            self.write_month(month)
        if year is not None:
            self.write_year(year)

    def __del__(self):
        self.bus.close()

# Signal handler to ensure proper cleanup
def signal_handler(sig, frame):
    print("Caught signal {}: Cleaning up...".format(sig))
    rtc.bus.close()
    exit(0)

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

# Example usage
rtc = DS1338RTC()
print(rtc.read_datetime())
rtc.write_all(seconds=30, minutes=45, hours=14, date=15, month=10, year=23)
print(rtc.read_datetime())

