        response = self._send_command(b'AT+CIFSR')
        if response:
            ip_start = response.find(b'STAIP:') + len(b'STAIP:')
            ip_end = response.find(b',')
            ip_address = response[ip_start:ip_end].decode()
            print(f"IP Address: {ip_address}")
            return ip_address
        else:
            print("Failed to get IP address.")
            return None

