import serial
import time
import datetime

# Constants
SERIAL_PORT = "/dev/ttyUSB0"
SERIAL_BAUDRATE = 9600
SERIAL_TIMEOUT = 1
LOG_FILE = "gps_coordinates_log.txt"

def parse_gpgga(gpgga_sentence):
    """Parse $GPGGA sentence to extract latitude, longitude, and altitude."""
    fields = gpgga_sentence.split(",")
    if len(fields) >= 9 and fields[6] == '1':  # Check if fix quality is valid
        latitude = fields[2]
        longitude = fields[4]
        altitude = fields[9]
        return latitude, longitude, altitude
    return None, None, None

def log_coordinates(latitude, longitude, altitude, timestamp):
    """Log GPS coordinates with an ISO 8601 timestamp to a file."""
    try:
        with open(LOG_FILE, "a") as log_file:
            log_file.write(f"{timestamp} - Latitude: {latitude}, Longitude: {longitude}, Altitude: {altitude}\n")
    except IOError as e:
        print(f"Error logging coordinates: {e}")

def main():
    try:
        ser = serial.Serial(SERIAL_PORT, SERIAL_BAUDRATE, timeout=SERIAL_TIMEOUT)
        print("Serial port initialized successfully.")

        while True:
            try:
                gps_data = ser.readline().decode('utf-8').strip()
                if gps_data.startswith("$GPGGA"):
                    latitude, longitude, altitude = parse_gpgga(gps_data)
                    if latitude and longitude and altitude:
                        timestamp = datetime.datetime.now().isoformat(timespec='seconds')
                        print(f"Latitude: {latitude}, Longitude: {longitude}, Altitude: {altitude}")
                        log_coordinates(latitude, longitude, altitude, timestamp)
            except KeyboardInterrupt:
                print("\nKeyboardInterrupt caught, exiting gracefully...")
                break
            except Exception as e:
                print(f"Error reading GPS data: {e}")

    except serial.SerialException as e:
        print(f"Error initializing serial port: {e}")

    finally:
        if 'ser' in locals() and ser.is_open:
            ser.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

import serial
import signal
import time

class GPSModule:
    def __init__(self, port='/dev/ttyAMA0', baud=9600):
        self.port = port
        self.baud = baud
        self.serial = None
        self.setup_signal_handler()

    def setup_signal_handler(self):
        def signal_handler(sig, frame):
            self.close()
            print('Exiting...')
            exit(0)

        signal.signal(signal.SIGINT, signal_handler)
        signal.signal(signal.SIGTERM, signal_handler)

    def __enter__(self):
        self.open()
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        self.close()

    def open(self):
        try:
            self.serial = serial.Serial(self.port, self.baud, timeout=1)
            if not self.serial.isOpen():
