logging.basicConfig(level=logging.INFO)

class SimpleGPS:
    def __init__(self, port='/dev/serial0', baudrate=9600):
        self.port = port
        self.baudrate = baudrate
        self.ser = None

    def connect(self):
        try:
            self.ser = serial.Serial(self.port, self.baudrate, timeout=1)
            logging.info(f"Connected to {self.port} at {self.baudrate} baud")
            return True
        except (serial.SerialException, OSError) as e:
            logging.error(f"Failed to connect to {self.port}: {e}")
            return False

    def read_data(self):
        if self.ser is None:
            return None

        try:
            data = self.ser.readline().decode('utf-8', errors='ignore').strip()
            if data:
                return data
            else:
                return None
        except serial.SerialException as e:
            logging.error(f"Serial error: {e}")
            return None

    def parse_gga(self, sentence):
        if not sentence.startswith('$GPGGA') and not sentence.startswith('$GNGGA'):
            logging.warning(f"Invalid GGA sentence: {sentence}")
            return None

        try:
            fields = sentence.split(',')
            utc_time = fields[1].split('.')[0]
            latitude = fields[2]
            longitude = fields[4]
            fix_quality = int(fields[6])
            num_satellites = int(fields[7])

            if latitude and longitude:
                latitude_deg = float(latitude) / 100.0
                if latitude[2] == 'S':
                    latitude_deg *= -1

                longitude_deg = float(longitude) / 100.0
                if longitude[3] == 'W':
                    longitude_deg *= -1

                return {
                    'utc_time': utc_time,
                    'latitude': latitude_deg,
                    'longitude': longitude_deg,
                    'fix_quality': fix_quality,
                    'num_satellites': num_satellites
                }
            else:
                return {
                    'utc_time': utc_time,
                    'latitude': None,
                    'longitude': None,
                    'fix_quality': fix_quality,
                    'num_satellites': num_satellites
                }
        except (IndexError, ValueError) as e:
            logging.error(f"Failed to parse GGA sentence: {e}")
            return None

    def close(self):
        if self.ser:
            try:
                self.ser.close()
                logging.info("Serial connection closed")
            except Exception as e:
                logging.error(f"Error closing serial connection: {e}")
            finally:
                self.ser = None

if __name__ == "__main__":
    gps = SimpleGPS()

    try:
        if not gps.connect():
            logging.error("Failed to connect to GPS")
            sys.exit(1)

        while True:
            data = gps.read_data()
            if data:
                parsed_data = gps.parse_gga(data)
                if parsed_data:
                    logging.info(f"Parsed GGA: {parsed_data}")
            time.sleep(0.1)

    except KeyboardInterrupt:
        logging.info("KeyboardInterrupt caught, closing connection...")
    finally:
        gps.close()
        logging.info("Exiting program")

