import flask
from flask import request, jsonify
import signal

class SerialCommunicator:
    def __init__(self, port, baudrate):
        self.port = port
        self.baudrate = baudrate
        self.lock = threading.Lock()
        self.serial = None

    def __enter__(self):
        self.open()
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        self.close()

    def open(self):
        with self.lock:
            if self.serial is None:
                try:
                    self.serial = pyserial.Serial(self.port, self.baudrate, timeout=1)
                except pyserial.SerialException as e:
                    raise e

    def send(self, cmd):
        with self.lock:
            if self.serial is not None:
                self.serial.write(cmd.encode('ascii'))
                self.serial.flush()

    def receive_line(self):
        with self.lock:
            if self.serial is not None:
                try:
                    return self.serial.readline().decode('ascii').strip()
                except pyserial.SerialException:
                    return None

    def close(self):
        with self.lock:
            if self.serial is not None:
                self.serial.close()
                self.serial = None

class DataManager:
    def __init__(self):
        self.data = [{'id': 1, 'name': 'Item 1', 'done': False}, {'id': 2, 'name': 'Item 2', 'done': True}]
        self.lock = threading.Lock()

    def get_all(self):
        with self.lock:
            return self.data

    def get_by_id(self, item_id):
        with self.lock:
            for item in self.data:
                if item['id'] == item_id:
                    return item
            return None

    def create(self, name, done):
        with self.lock:
            if not name or not isinstance(done, bool):
                return None
            new_item = {'id': len(self.data) + 1, 'name': name, 'done': done}
            self.data.append(new_item)
            return new_item

app = flask.Flask(__name__)
data_manager = DataManager()
serial_comm = SerialCommunicator('/dev/ttyUSB0', 9600)

@app.route('/version', methods=['GET'])
def version():
    try:
        with serial_comm:
            serial_comm.send('*IDN?\n')
            response = serial_comm.receive_line()
            if response is None:
                return flask.Response('504', mimetype='text/plain')
            return flask.Response(response, mimetype='text/plain')
    except pyserial.SerialException:
        return flask.Response('500', mimetype='text/plain')
    finally:
        serial_comm.close()

@app.route('/data', methods=['GET'])
def get_all_data():
    data = data_manager.get_all()
    return jsonify(data)

@app.route('/data/<int:item_id>', methods=['GET'])
def get_data_by_id(item_id):
    item = data_manager.get_by_id(item_id)
    if item is None:
        return flask.Response('404', mimetype='application/json')
    return jsonify(item)

@app.route('/data', methods=['POST'])
def create_data():
    name = request.json.get('name')
    done = request.json.get('done')
    new_item = data_manager.create(name, done)
    if new_item is None:
        return flask.Response('400', mimetype='application/json')
    return jsonify(new_item), 201

def signal_handler(sig, frame):
    serial_comm.close()
    app.run_reloader = False
    app.run(host='0.0.0.0', port=5000, debug=False)

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

if __name__ == '__main__':
    signal_handler(None, None)

