@app.route('/getdata')
def get_data():
    return jsonify(data_store)

@app.route('/getset/<int:item_id>')
def get_set(item_id):
    for item in data_store:
        if item['id'] == item_id:
            return jsonify(item)
    abort(404)

@app.route('/getpost/<int:item_id>/<name>')
def get_post(item_id, name):
    for item in data_store:
        if item['id'] == item_id:
            item['name'] = name
            return jsonify(data_store)
    abort(404)

@app.route('/postjson', methods=['POST'])
def post_json():
    if request.content_type == 'application/json':
        try:
            data = request.get_json()
            new_id = max(item['id'] for item in data_store) + 1
            data_store.append({
                'id': new_id,
                'name': data.get('name', ''),
                'done': data.get('done', False)
            })
            return jsonify(data_store)
        except (ValueError, TypeError):
            return "Bad Request: Invalid JSON", 400
    elif request.content_type == 'application/x-www-form-urlencoded':
        try:
            name = request.form.get('name', '')
            done = request.form.get('done', 'False')
            done = done.lower() in ['true', '1', 't', 'y', 'yes']
            new_id = max(item['id'] for item in data_store) + 1
            data_store.append({
                'id': new_id,
                'name': name,
                'done': done
            })
            return jsonify(data_store)
        except Exception as e:
            return "Bad Request: Invalid form data", 400
    else:
        return "Unsupported Content-Type", 415

@app.route('/postjson')
def get_postjson():
    return jsonify(data_store)

if __name__ == '__main__':
    app.run(host='0.0.0.0')
```

This Flask application manages an in-memory data store and communicates with a serial-connected SCPI-compatible instrument. It handles various routes for interacting with the data store and the instrument, ensuring proper error handling and resource management.

